import{_ as r,l,o as e,c as n,v as o,p as s,x as t,d as c,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"音乐生成","description":"","frontmatter":{"title":"音乐生成","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/music-generation.md","filePath":"llm/music-generation.md","lastUpdated":1789023840000}'),p={name:"llm/music-generation.md"};function u(h,a,_,E,f,A){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="音乐生成" tabindex="-1">音乐生成 <a class="header-anchor" href="#音乐生成" aria-label="Permalink to &quot;音乐生成&quot;">​</a></h1><div class="epigraph"><p>歌曲要在分钟级保持调性、节奏与结构。局部听着像音乐，并不等于会反复、会收束。</p><footer>—— Copet 等 MusicGen；Agostinelli 等 MusicLM；Dhariwal 等 Jukebox</footer></div><p><a href="/llm/e2e-speech-dialogue">上一课</a>的音频是对话轮次，秒到十几秒。<a href="/llm/valle-tts">VALL-E</a> 的 codec LM 可迁到音乐，但目标从音色克隆变成长程结构。缺口是条件（文本描述、旋律、和弦）与分钟级一致性。后课 omni 默认各模态生成器已经能各自出流，再谈对齐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Jukebox 在量化码上分层 AR，能长，但慢、文本控制弱。MusicLM 用级联音频表示与联合文本–音频嵌入。MusicGen 用 EnCodec 码 + 单一 Transformer，文本或旋律（音频条件）可控，强调简单可复现。长程失败：调漂移、段落进不去副歌、鼓点与旋律脱拍——类似视频闪烁，但是在节拍网格上。</p><p><span class="marginnote">旋律条件通常是把哼唱或单音轨编成条件码，不是乐谱解析。没有对齐的乐谱时，模型学的是声学相关，不是明确的和声功能。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>表示：codec token 或连续潜变量 + 扩散/流。条件：文本、风格标签、旋律、歌词（歌词要另做对齐，见音画课的时间问题）。训练用长上下文或分段 + 记忆。评测：人评结构与文本遵守、FAD，不要用对话 WER。版权与训练数据来源必须单独披露，不能只报听感。</p>',8)),(e(),s(m,null,{default:t(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CND%5B%22%E6%96%87%E6%9C%AC%E6%88%96%E6%97%8B%E5%BE%8B%22%5D%20--%3E%20LM%5B%22%E9%9F%B3%E9%A2%91%20Transformer%20%E6%88%96%E6%89%A9%E6%95%A3%22%5D%0A%20%20LM%20--%3E%20TOK%5B%22codec%20%E6%88%96%E6%BD%9C%E5%8F%98%E9%87%8F%22%5D%0A%20%20TOK%20--%3E%20WAV%5B%22%E6%B3%A2%E5%BD%A2%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>节拍是时间上的周期结构，模型必须在位置编码或显式节拍条件里看见它，否则只有局部纹理。这与 <a href="/llm/2d-rope">2D RoPE</a> 给图像格子、视频给绝对时间是同一教训：生成器不自动拥有正确的轴。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>音乐生成仍常是单模态音频。下一课把视、听、说装进一个要对齐的 omni 模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>音乐生成的硬问题是长程结构与可控条件，不是短窗听感。</li><li>codec AR（MusicGen）与级联（MusicLM）是两条产品路。</li><li>节拍与调性需要时间协议，不能指望局部 CE。</li><li>出处：MusicGen；MusicLM；Jukebox。</li></ul>',6))])}const b=r(p,[["render",u]]);export{M as __pageData,b as default};
